def update_cumulations():
    for pk in fes:
        updated = FolhaEvento.objects.filter(pk=pk).update(
            correct_qnt=fes[pk][0],
            correct_valor=fes[pk][1],
            correct_contribution_base=fes[pk][1],
        )
        if not updated:
            print(pk)
